import { AppState } from 'react-native';

const suscripcion = AppState.addEventListener('change', (siguiente) => {
  // 'active' | 'background' | 'inactive' (este último, solo en iOS)
  if (siguiente !== 'active') {
    guardarYa(); // escribe en el disco lo que esté pendiente
  }
});

// Cuando el componente o el módulo ya no lo necesita:
suscripcion.remove();

const disco = new Map();
const AsyncStorage = { multiSet: async (l) => { for (const [k, v] of l) disco.set(k, v); } };
const pendientes = new Map();
let reloj = null;

function guardarYa() {
  if (reloj) clearTimeout(reloj);
  reloj = null;
  if (!pendientes.size) return;
  const lote = [];
  pendientes.forEach((v, k) => lote.push([k, JSON.stringify(v)]));
  pendientes.clear();
  AsyncStorage.multiSet(lote);
}

function setItem(k, v) {
  pendientes.set(k, v);
  if (!reloj) reloj = setTimeout(guardarYa, 400); // un solo reloj por lote
}

setItem('senda-usuario', { talentos: 115 }); // t = 0: ganás Talentos
setTimeout(() => {
  console.log('a los 300 ms, en disco:', disco.get('senda-usuario') ?? 'nada');
}, 300);
setTimeout(() => {
  console.log('a los 500 ms, en disco:', disco.get('senda-usuario') ?? 'nada');
}, 500);

